/* aesthetic fold v2.17.1 — generated by scripts/build-registry.mjs. */
@import './aesthetic.base.css';

:root {
  --ae-ink-muted: #737373;
  --ae-line: #e9e9e9;
  --ae-ink-muted-dark: #8f8f8f;
  --ae-line-dark: #262626;
  --ae-w-medium: 550;
  --ae-space-4: 1em;
  --ae-space-5: 1.5em;
  --ae-soft: 240ms;
}

@media (prefers-color-scheme: dark) {
  :root:not(.light):not([data-ae-mode='light']) {
    --ae-ink-muted: var(--ae-ink-muted-dark);
    --ae-line: var(--ae-line-dark);
  }
}

.light,
[data-ae-mode='light'] {
  color-scheme: light;
}

:root.dark,
:root[data-ae-mode='dark'] {
  color-scheme: dark;
  --ae-ink-muted: var(--ae-ink-muted-dark);
  --ae-line: var(--ae-line-dark);
}

.ae-dim {
color: var(--ae-ink-muted);
}

details.ae-fold {
border-top: 1px solid var(--ae-line);
}

details.ae-fold:last-of-type {
border-bottom: 1px solid var(--ae-line);
}

.ae-fold summary {
list-style: none;
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: var(--ae-space-5);
  padding: 0.8em 0;
  font-weight: var(--ae-w-medium);
  cursor: pointer;
}

.ae-fold summary::marker {
content: '';
}

.ae-fold summary::after {
content: '+';
  font-family: var(--ae-font-mono);
  font-weight: var(--ae-w-regular);
  color: var(--ae-ink-muted);
  transition: rotate var(--ae-soft) var(--ae-ease);
}

.ae-fold[open] summary::after {
rotate: 45deg;
}

.ae-fold > :not(summary) {
padding-bottom: var(--ae-space-4);
}
